{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p, service_name, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, sum(CASE WHEN duration>1e9 THEN 1 ELSE 0 END) n_over_1s FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-basic-service' AND span_name='BasicController.queryForTravel' GROUP BY ALL ORDER BY p", "claim": "BasicController.queryForTravel takes about 1731 ms in all 24 abnormal calls, versus 18 ms normally, with no slow children."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name IN ('BasicController.queryForTravel','POST /api/v1/basicservice/basic/travel','BasicController.queryForTravels') GROUP BY ALL", "claim": "The slow basic endpoint /basic/travel is slow in its own Internal method span; the sibling /basic/travels endpoint stays around 12 ms."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(quantile_cont(s.duration,0.5)/1e6,1) p50_ms, round(max(c.duration)/1e6,1) max_client_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-travel-service' AND s.service_name='ts-basic-service' AND s.span_name='POST /api/v1/basicservice/basic/travel' GROUP BY ALL", "claim": "Travel's client calls to basic /basic/travel take about 1732 ms, matching basic's slow server span."}
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-preserve-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(quantile_cont(s.duration,0.5)/1e6,1) p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-preserve-service' AND s.service_name='ts-travel-service' AND s.span_name='POST /api/v1/travelservice/trip_detail' GROUP BY ALL", "claim": "Preserve's calls to travel trip_detail take about 1761 ms, inheriting basic's delay."}
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(quantile_cont(s.duration,0.5)/1e6,1) p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-preserve-service' GROUP BY ALL", "claim": "UI dashboard's calls to preserve take about 3538 ms, up from about 141 ms p95 normally."}
      ]
    }
  ]
}
